const first = $input.first().json;
const fallbackMarkets = String(first.candidate_universe || '').split(',').map(v => v.trim()).filter(Boolean);
const sourceTickers = Array.isArray(first.tickers) && first.tickers.length
  ? first.tickers
  : fallbackMarkets.map((market, index) => ({
      market,
      trade_price: 0,
      signed_change_rate: 0,
      acc_trade_price_24h: 0,
      acc_trade_volume_24h: 0,
      high_price: 0,
      low_price: 0,
      simulated_input: true,
      fallback_rank: index + 1
    }));
const allowed = new Set(fallbackMarkets);
const minVolume = Number(first.min_24h_krw_volume || 0);
const maxCandidates = Number(first.max_candidates || 3);
const candidates = sourceTickers
  .filter(row => row.market && row.market.startsWith('KRW-') && (!allowed.size || allowed.has(row.market)))
  .map(row => {
    const price = Number(row.trade_price || 0);
    const changeRate = Number(row.signed_change_rate || 0);
    const volumeKrw = Number(row.acc_trade_price_24h || 0);
    const high = Number(row.high_price || 0);
    const low = Number(row.low_price || 0);
    const range = high > 0 && low > 0 ? (high - low) / price : 0;
    const liquidityScore = Math.min(volumeKrw / Math.max(minVolume, 1), 2) / 2;
    const momentumScore = Math.max(Math.min((changeRate + 0.08) / 0.16, 1), 0);
    const volatilityPenalty = Math.min(range, 0.15);
    const finalScore = Number((liquidityScore * 0.45 + momentumScore * 0.45 - volatilityPenalty * 0.10).toFixed(4));
    return {
      market: row.market,
      strategy_profile: first.strategy_profile || 'conservative_momentum',
      trade_price: price,
      signed_change_rate: changeRate,
      acc_trade_price_24h: volumeKrw,
      volatility_range: Number(range.toFixed(6)),
      liquidity_ok: volumeKrw >= minVolume,
      final_score: finalScore,
      selected: false,
      execution_allowed: false,
      reason: 'reference_only_until_precheck_passes'
    };
  })
  .sort((a, b) => b.final_score - a.final_score)
  .map((row, index) => ({ ...row, rank: index + 1, selected: index < maxCandidates && row.liquidity_ok }));
return candidates.map(candidate => ({ json: candidate }));

return [{
  json: {
    ...$json,
    candidate_status: $json.selected ? 'selected_reference_only' : 'not_selected',
    execution_allowed: false,
    handoff_note: 'WF03 must validate balances, open orders, order chance, order test, and explicit live gate.'
  }
}];
